using System.IO.Compression;
using System.Text.Json;
using System.Text;
using static Studio.Database;
namespace Studio;
public record ArchiveSceneVersion(string SceneId,string Id,JsonElement Document);
public record ProjectArchiveInfo(string Name,string[] SceneIds,JsonElement? ProjectDocument);
public sealed class ProjectArchiveService(Database database,StudioService scenes,LibraryService library,DocumentContract contract,ObjectStore objects,SemanticService semantics)
{
 private static JsonElement Parse(string value)=>JsonDocument.Parse(value).RootElement.Clone();
 private JsonElement? Graph(string id){try{return library.Read("project",id).Document;}catch(ApiException e)when(e.Status==404){return null;}}
 private LibraryResponse[] LibraryClosure(IEnumerable<JsonElement> documents){
  var records=new Dictionary<string,LibraryResponse>();void Visit(JsonElement doc){
   if(doc.TryGetProperty("prefabs",out var instances))foreach(var instance in instances.EnumerateArray()){var id=DocumentContract.Text(instance,"prefabId");var version=DocumentContract.Text(instance,"revisionId");if(records.ContainsKey(version))continue;var record=library.Read("prefab",id,version);records[version]=record;Visit(record.Document.GetProperty("document"));}
   foreach(var entity in contract.Compile(doc).GetProperty("entities").EnumerateArray())foreach(var c in entity.GetProperty("components").EnumerateArray())if(DocumentContract.Text(c,"type")=="studio.configurator.Catalog"){var data=c.GetProperty("data");var version=DocumentContract.Text(data,"libraryVersionId");if(version!=""&&!records.ContainsKey(version))records[version]=library.Read("catalog",DocumentContract.Text(data,"catalogId"),version);}
  }foreach(var doc in documents)Visit(doc);return records.Values.ToArray();
 }
 private ArchiveSceneVersion[] PinnedVersions(JsonElement? graph){
  if(!graph.HasValue)return[];var ids=graph.Value.GetProperty("nodes").EnumerateArray().Select(n=>DocumentContract.Text(n,"sceneVersionId")).Append(DocumentContract.Text(graph.Value,"skinSceneVersionId")).Where(id=>id!="").Distinct();using var db=database.Open();return ids.Select(id=>{var row=db.Ado.SqlQuery<VersionRow>("SELECT * FROM Versions WHERE Id=@id",P("id",id)).SingleOrDefault()??throw new ApiException(422,"固定场景版本缺失");return new ArchiveSceneVersion(row.SceneId,row.Id,Parse(row.Document));}).ToArray();
 }
 public DraftResponse Copy(string id){using var db=database.Open();var project=db.Ado.SqlQuery<ProjectRow>("SELECT * FROM Projects WHERE Id=@id",P("id",id)).SingleOrDefault()??throw new ApiException(404,"工程不存在");var documents=scenes.Scenes(id).Select(s=>s.Document).ToArray();var graph=Graph(id);return scenes.CreateCollection(project.Name+" 副本",documents,graph,[],PinnedVersions(graph));}
 public async Task Export(string id,Stream output,CancellationToken ct){
  using var db=database.Open();var project=db.Ado.SqlQuery<ProjectRow>("SELECT * FROM Projects WHERE Id=@id",P("id",id)).SingleOrDefault()??throw new ApiException(404,"工程不存在");var documents=scenes.Scenes(id);if(documents.Length==0)throw new ApiException(422,"工程没有场景");var graph=Graph(id);var pinned=PinnedVersions(graph);var allDocuments=documents.Select(d=>d.Document).Concat(pinned.Select(v=>v.Document)).ToArray();var assets=new Dictionary<string,AssetResponse>();foreach(var document in allDocuments)foreach(var asset in contract.Compile(document).GetProperty("assets").EnumerateArray()){var stored=objects.Get(DocumentContract.Text(asset,"id"));assets[stored.Id]=stored;}if(graph.HasValue)foreach(var asset in graph.Value.GetProperty("assets").EnumerateArray()){var stored=objects.Get(DocumentContract.Text(asset,"id"));assets[stored.Id]=stored;}
  var libraryRecords=LibraryClosure(allDocuments);foreach(var record in libraryRecords)foreach(var assetId in contract.LibraryAssetIds(record.Kind=="prefab"?"studio.prefab.Definition":"studio.configurator.Catalog",record.Document)){var stored=objects.Get(assetId);assets[stored.Id]=stored;}
  using var zip=new ZipArchive(output,ZipArchiveMode.Create,true);async Task JsonFile(string path,byte[] bytes){await using var stream=zip.CreateEntry(path).Open();await stream.WriteAsync(bytes,ct);}
  await JsonFile("archive.json",JsonSerializer.SerializeToUtf8Bytes(new ProjectArchiveInfo(project.Name,documents.Select(d=>d.SceneId).ToArray(),graph),ApiJson.Default.ProjectArchiveInfo));
  await JsonFile("assets.json",JsonSerializer.SerializeToUtf8Bytes(assets.Values.ToArray(),ApiJson.Default.AssetResponseArray));
  foreach(var document in documents)await JsonFile("scenes/"+document.SceneId+".json",Encoding.UTF8.GetBytes(document.Document.GetRawText()));
  foreach(var version in pinned)await JsonFile("scene-versions/"+version.SceneId+"/"+version.Id+".json",JsonSerializer.SerializeToUtf8Bytes(version,ApiJson.Default.ArchiveSceneVersion));
  foreach(var template in libraryRecords)await JsonFile("library/"+template.Kind+"/"+template.Id+"/"+template.VersionId+".json",JsonSerializer.SerializeToUtf8Bytes(template,ApiJson.Default.LibraryResponse));
  foreach(var asset in assets.Values)foreach(var file in asset.Files.Concat(asset.Preview is {} preview?[preview.File]:Array.Empty<string>())){await using var stream=zip.CreateEntry("assets/"+asset.Id+"/"+file).Open();await objects.CopyTo("assets/"+asset.Id+"/"+file,stream,ct);}
 }
 public async Task<DraftResponse> Import(Stream input,CancellationToken ct){
  var temp=Path.Combine(Path.GetTempPath(),"studio-project-"+Id()+".zip");try{
   await using(var stream=File.Create(temp))await input.CopyToAsync(stream,ct);using var zip=ZipFile.OpenRead(temp);if(zip.Entries.Count>20000||zip.Entries.Sum(e=>e.Length)>2L*1024*1024*1024)throw new ApiException(413,"工程包超过解包预算");
   async Task<JsonElement> JsonFile(string path){var entry=zip.GetEntry(path)??throw new ApiException(422,"工程包缺少 "+path);await using var stream=entry.Open();using var json=await JsonDocument.ParseAsync(stream,cancellationToken:ct);return json.RootElement.Clone();}
   ProjectArchiveInfo info;JsonElement[] documents;
   if(zip.GetEntry("archive.json")!=null){info=JsonSerializer.Deserialize((await JsonFile("archive.json")).GetRawText(),ApiJson.Default.ProjectArchiveInfo)??throw new ApiException(422,"工程包元数据无效");if(info.SceneIds.Length==0||info.SceneIds.Distinct().Count()!=info.SceneIds.Length)throw new ApiException(422,"场景目录为空或重复");var loaded=new List<JsonElement>();foreach(var id in info.SceneIds){var doc=DocumentContract.Migrate(await JsonFile("scenes/"+id+".json"));if(DocumentContract.Text(doc,"sceneId")!=id)throw new ApiException(422,"场景目录与文档 ID 不一致");loaded.Add(doc);}documents=loaded.ToArray();}
   else{var document=DocumentContract.Migrate(await JsonFile("document.json"));documents=[document];info=new(DocumentContract.Text(document,"name"),[DocumentContract.Text(document,"sceneId")],null);}
   foreach(var document in documents)contract.Assert(document);var templates=new List<LibraryResponse>();foreach(var entry in zip.Entries.Where(e=>(e.FullName.StartsWith("templates/",StringComparison.Ordinal)||e.FullName.StartsWith("library/",StringComparison.Ordinal))&&e.FullName.EndsWith(".json",StringComparison.Ordinal)))templates.Add(JsonSerializer.Deserialize((await JsonFile(entry.FullName)).GetRawText(),ApiJson.Default.LibraryResponse)??throw new ApiException(422,"模板归档无效"));
   var pinned=new List<ArchiveSceneVersion>();foreach(var entry in zip.Entries.Where(e=>e.FullName.StartsWith("scene-versions/",StringComparison.Ordinal)&&e.FullName.EndsWith(".json",StringComparison.Ordinal)))pinned.Add(JsonSerializer.Deserialize((await JsonFile(entry.FullName)).GetRawText(),ApiJson.Default.ArchiveSceneVersion)??throw new ApiException(422,"固定场景归档无效"));
   var assets=new Dictionary<string,JsonElement>();foreach(var document in documents.Concat(pinned.Select(v=>v.Document)))foreach(var asset in contract.Compile(document).GetProperty("assets").EnumerateArray())assets[DocumentContract.Text(asset,"id")]=asset.Clone();if(info.ProjectDocument.HasValue)foreach(var asset in info.ProjectDocument.Value.GetProperty("assets").EnumerateArray())assets[DocumentContract.Text(asset,"id")]=asset.Clone();
   if(zip.GetEntry("assets.json")!=null)foreach(var asset in (await JsonFile("assets.json")).EnumerateArray())assets[DocumentContract.Text(asset,"id")]=asset.Clone();
   foreach(var(id,asset)in assets){var bundlePath=Path.Combine(Path.GetTempPath(),"studio-asset-"+Id()+".zip");try{using(var bundle=ZipFile.Open(bundlePath,ZipArchiveMode.Create))foreach(var name in asset.GetProperty("files").EnumerateArray().Select(f=>f.GetString()!)){if(!ObjectStore.ValidPath(name))throw new ApiException(422,"资源路径无效");var content=zip.GetEntry("assets/"+id+"/"+name)??throw new ApiException(422,"归档资源缺失 "+name);await using var from=content.Open();await using var to=bundle.CreateEntry(name).Open();await from.CopyToAsync(to,ct);}await using var upload=File.OpenRead(bundlePath);var stored=await objects.Upload(upload,DocumentContract.Text(asset,"name"),DocumentContract.Text(asset,"kind"),DocumentContract.Text(asset,"entry"),ct);if(stored.Id!=id||stored.Sha256!=DocumentContract.Text(asset,"sha256"))throw new ApiException(422,"归档资源摘要不一致");if(asset.TryGetProperty("preview",out var preview)&&preview.ValueKind==JsonValueKind.Object){var name=DocumentContract.Text(preview,"file");if(!ObjectStore.ValidPath(name))throw new ApiException(422,"缩略图路径无效");var content=zip.GetEntry("assets/"+id+"/"+name)??throw new ApiException(422,"缩略图归档缺失");await using var stream=content.Open();await objects.Preview(id,stream,preview.GetProperty("width").GetInt32(),preview.GetProperty("height").GetInt32(),ct);}if(stored.Kind=="semantic")await semantics.Index(stored.Id,ct);}finally{File.Delete(bundlePath);}}
   return scenes.CreateCollection(info.Name,documents,info.ProjectDocument,templates.ToArray(),pinned.ToArray());
  }finally{File.Delete(temp);}
 }
}
